#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNostrTransport: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = NostrTransport

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> NostrTransport {
        return NostrTransport(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: NostrTransport) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NostrTransport {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: NostrTransport, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNostrTransport_lift(_ pointer: UnsafeMutableRawPointer) throws -> NostrTransport {
    return try FfiConverterTypeNostrTransport.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNostrTransport_lower(_ value: NostrTransport) -> UnsafeMutableRawPointer {
    return FfiConverterTypeNostrTransport.lower(value)
}






/**
 * The bounded-spend delegate surface, as one opaque handle.
 *
 * Build it once per app and keep it: it holds the intent store an escalation
 * parks in.
 */
public protocol PaygentAgentProtocol: AnyObject, Sendable {
    
    /**
     * Whether an intent may be executed silently or has to reach the owner
     * (RFC-0014).
     *
     * Does not throw: the engine fails CLOSED, so an unreadable limit or an
     * unreachable chain returns an escalate decision rather than an error the
     * caller could mistake for "no policy applies".
     */
    func agentAuthorize(intent: PolicyIntent, authLevel: AuthLevel, ctx: CommandContext) async  -> PolicyDecision
    
    /**
     * Block until a parked operation leaves `AwaitingAuthorization`, or
     * `wait_ms` elapses. JSON `Intent`, or JSON `null` when the intent
     * vanished or the wait expired.
     *
     * String for the same reason as [`agent_intent`](Self::agent_intent).
     */
    func agentAwaitIntent(intentId: String, waitMs: UInt32) async throws  -> String
    
    /**
     * Token balances.
     */
    func agentBalances(wallet: String, chainId: UInt64?) async throws  -> [TokenBalance]
    
    /**
     * Deploy the wallet on one chain. Returns the UserOp hash.
     */
    func agentDeployWallet(request: DeployUserOpRequest) async throws  -> UserOpHash
    
    /**
     * Ask the owner to authorize an x402 payment this client may not make
     * silently. Returns the `Eip3009Authorization` they signed.
     */
    func agentEscalateX402Authorization(request: X402EscalationRequest) async throws  -> Eip3009Authorization
    
    /**
     * A parked operation, by id. JSON `Intent`, or JSON `null` when no such
     * intent exists.
     *
     * Still a string, deliberately. `Intent` carries `input` / `result` as
     * `serde_json::Value` (no representation in any binding), three
     * `DateTime<Utc>` fields, and a 14-variant `SigningIntent` each of whose
     * variants wraps its own relay-wire struct. Typing it is an SDK shape
     * question -- what a debugging read should actually expose -- not a
     * binding question, and contorting it to make a count come out at 13
     * would be the wrong answer to it.
     */
    func agentIntent(intentId: String) throws  -> String
    
    /**
     * What this agent may spend on `wallet` for `token`, read from the chain:
     * its executor module (derived from the host's own key), whether that
     * module is deployed and enabled, and the limit the guard the Safe
     * enforces holds for it (RFC-0065 S5).
     *
     * A read that fails throws. It never answers `module_enabled: false` or a
     * limit of zero for a chain it could not reach.
     */
    func agentMandate(wallet: String, chainId: UInt64, token: String) async throws  -> AgentMandate
    
    /**
     * The networks this client supports and whether the wallet is deployed on
     * each. JSON `NetworkSummary[]`.
     *
     * The one read still crossing as a string, and the reason is a name, not a
     * shape: `NetworkSummary` carries a `ChainFamily`, and this crate already
     * exports a DIFFERENT `ChainFamily` (the pairing QR's, in `pairing.rs`).
     * UniFFI names a type by its Rust identifier with no rename, and Swift
     * puts every namespace in one flat module, so deriving the second one
     * would be a redeclaration error in the iOS host while Android -- whose
     * namespaces are separate Kotlin packages -- compiled fine. Typing this
     * op means renaming one of the two first, which is a host-visible change
     * and belongs in its own commit.
     */
    func agentNetworks(wallet: String?) async throws  -> String
    
    /**
     * Fetch a URL, and pay for it if the server demands payment.
     *
     * One method for every payment protocol: which one the server speaks is
     * read off its `402` and reported on the result, never asked for. So a
     * Swift or Kotlin caller names a resource and a ceiling, and never a
     * rail.
     *
     * This binding declares one payer, for the x402 rail, and it pays with the
     * agent's own key through the wallet's on-chain executor module. So an
     * x402 `402` on a host whose [`AgentHost::signer_backing`] is
     * [`AgentSignerBacking::DeviceHardware`] is signed and settled SILENTLY,
     * within the mandate the owner set on-chain, and comes back as
     * [`PayResult::PaidAndServed`] with `rail: "x402"`: money moves without
     * a prompt on this device. A host with no hardware key, or a demand the
     * module cannot settle, comes back as [`PayResult::OwnerApprovalNeeded`]
     * with `rail: "x402"`, and the app takes it to
     * [`Self::agent_escalate_x402_authorization`]. A `402` on any other rail
     * is refused by name -- no payer is declared for it, and that refusal is
     * what stops an unwired rail being reported as a payment the owner could
     * approve. A `PayResult` is the answer either way.
     *
     * [`PayResult::PaidNotServed`] is a RESULT, not an error: the money is
     * gone and the resource is not, on rails with no refund path. A host that
     * only inspects thrown errors will miss it.
     *
     * A throw is almost always "the attempt could never be made", and safe to
     * retry -- but not always, so a host must not build a blanket retry on
     * it. A plain `200` that arrives carrying a settlement receipt is refused
     * rather than reported as free (money moved that this call cannot account
     * for), and the receipt travels out in the message: it is then the only
     * record of that spend, so log the text rather than a category. Every
     * `PayError` reaches Kotlin and Swift as [`MobileError::Rpc`], as on every
     * other operation here, because the browser binding can carry nothing
     * richer than a message either and one shared answer is worth more than a
     * per-host taxonomy.
     */
    func agentPay(call: PayCall) async throws  -> PayResult
    
    /**
     * Top the pocket up from the treasury vault, inside the on-chain
     * silent-refill allowance. `amount` is base units as a decimal string --
     * the money crosses as text so no host language's number type can round
     * it, which is the same reason the transfer amount is hex.
     */
    func agentRefillSolanaPocket(network: String, mint: String, amount: String) async throws  -> SolanaPocketReceipt
    
    /**
     * What is known about the wallet this client acts for.
     *
     * Does not throw: a session that cannot be read is the empty snapshot,
     * which every caller already treats as "no wallet" and refuses to spend
     * from.
     */
    func agentSession(wallet: String?) async  -> SessionSnapshot
    
    /**
     * The agent's Solana pocket for `(network, mint)`.
     */
    func agentSolanaPocket(network: String, mint: String) async throws  -> SolanaPocketInfo
    
    /**
     * Return the pocket's residual balance to the vault. `None` when there
     * was nothing to sweep -- a real absence the binding carries natively,
     * rather than the string `"null"` a caller had to notice and parse.
     */
    func agentSweepSolanaPocket(network: String, mint: String) async throws  -> SolanaPocketReceipt?
    
    /**
     * Transaction history.
     */
    func agentTransactions(wallet: String, chainId: UInt64?, limit: UInt32?, offset: UInt32?) async throws  -> [TransactionSummary]
    
    /**
     * Move ETH or an ERC-20 out of the wallet over the sponsored ERC-4337
     * rail. Returns the UserOp hash.
     *
     * `amount_base_units` is a `U256`, which neither binding has a number for
     * -- it crosses as a string. This crate's exported
     * `amount_decimal_to_u256_hex` (`amountDecimalToU256Hex` in Swift and
     * Kotlin) turns a human decimal
     * amount into the `0x`-prefixed hex form `paygent-sdk::fixtures` pins, so
     * a host that built the amount with it hands over what this reads. A bare
     * decimal base-units string is read too, and as decimal: the lift is
     * `ruint`'s `FromStr`, the same parse the browser's `serde` path uses.
     *
     * This does not consult the mandate. Call
     * [`agent_authorize`](Self::agent_authorize) first and escalate when it
     * says so -- sending regardless is not a way past the limit, because the
     * on-chain guard rejects an over-cap transfer, but it burns a UserOp to
     * find out.
     */
    func agentTransfer(request: TransferUserOpRequest) async throws  -> UserOpHash
    
}
