/**
 * One guarded administrative submission. Build it, admit it against what an
 * atomic read-and-drop of the record returned, arm it before the network call,
 * and settle it once the call has answered or failed.
 */
public protocol SubmitGuardProtocol: AnyObject, Sendable {
    
