/**
 * Result of [`prepare_binding`]: the 32-byte hash `W` signs as its WebAuthn
 * challenge to bind the device key, plus the canonical statement that hash
 * digests (so the native side can display/log what is being attested without
 * recomputing it).
 */
public struct BindingPrep {
    /**
     * `SHA256(statement)`. Pass this as the challenge to the platform WebAuthn
     * `signAssertion` call; [`complete_binding`] expects the assertion over it.
     */
    public var hashToSign: Data
    /**
     * The exact statement `W` is attesting, `paygent-binding:v1:issuer=...:owner=...`.
     */
    public var statement: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * `SHA256(statement)`. Pass this as the challenge to the platform WebAuthn
         * `signAssertion` call; [`complete_binding`] expects the assertion over it.
         */hashToSign: Data, 
        /**
         * The exact statement `W` is attesting, `paygent-binding:v1:issuer=...:owner=...`.
         */statement: String) {
        self.hashToSign = hashToSign
        self.statement = statement
    }
}

#if compiler(>=6)
extension BindingPrep: Sendable {}
#endif


extension BindingPrep: Equatable, Hashable {
    public static func ==(lhs: BindingPrep, rhs: BindingPrep) -> Bool {
        if lhs.hashToSign != rhs.hashToSign {
            return false
        }
        if lhs.statement != rhs.statement {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(hashToSign)
        hasher.combine(statement)
    }
}



