         */webauthnSigner: String, 
        /**
         * SafeModuleGuard address on this chain (optional; required only for
         * spending-limit operations).
         */safeModuleGuard: String?, 
        /**
         * P256ExecutorModule address on this chain (optional; required for
         * spending-limit ops that reference the module).
         */p256ExecutorModule: String?) {
        self.chainId = chainId
        self.rpcUrl = rpcUrl
        self.bundlerUrl = bundlerUrl
        self.safe = safe
