/**
 * The unified owner list plus the divergence a user must be able to rectify.
 */
public struct ChainSyncReportFfi {
    public var chains: [ChainOwnerStateFfi]
    /**
     * Deployed chains whose owner set could not be read. Reported, never judged.
     */
    public var unreadable: [UnreadableChainFfi]
    public var rows: [UnifiedOwnerRowFfi]
    public var thresholdByChain: [String: UInt32]
    /**
     * On-chain owners that could not be mapped to any known identity, per chain
     * (e.g. an owner added from another device whose passkey this app has not
     * seen). Surfaced so they are never silently dropped from the unified view.
     */
    public var unlinkedByChain: [String: [String]]
    public var thresholdDiverges: Bool
    public var ownersDiverge: Bool
    public var hasUnlinked: Bool
    public var hasDrift: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chains: [ChainOwnerStateFfi], 
        /**
         * Deployed chains whose owner set could not be read. Reported, never judged.
