        /**
         * On-chain owners that could not be mapped to any known identity, per chain
         * (e.g. an owner added from another device whose passkey this app has not
         * seen). Surfaced so they are never silently dropped from the unified view.
         */unlinkedByChain: [String: [String]], thresholdDiverges: Bool, ownersDiverge: Bool, hasUnlinked: Bool, hasDrift: Bool) {
        self.chains = chains
        self.unreadable = unreadable
        self.rows = rows
        self.thresholdByChain = thresholdByChain
        self.unlinkedByChain = unlinkedByChain
        self.thresholdDiverges = thresholdDiverges
        self.ownersDiverge = ownersDiverge
        self.hasUnlinked = hasUnlinked
        self.hasDrift = hasDrift
    }
}

