/**
 * How the channel toward one side-wallet pocket stands, for a funding screen.
 *
 * There is no single "balance" to show on this rail, which is why this is a
 * handful of values rather than a number: sats sitting in the on-chain wallet
 * cannot be paid, sats in a channel that has not confirmed yet cannot be paid,
 * and sats in a confirmed channel whose peer is offline cannot be paid either.
 */
public struct LightningChannelFfi {
    /**
     * Total sats committed when the channel was opened.
     */
    public var channelValueSats: UInt64
    /**
     * What can still be sent over this channel, in millisats. This is the
     * ceiling on the next top-up, not `channel_value_sats`.
     */
    public var outboundCapacityMsat: UInt64
    /**
     * What the pocket could send back, in millisats.
     */
    public var inboundCapacityMsat: UInt64
    /**
     * The funding transaction has the confirmations the peer required.
     */
    public var isChannelReady: Bool
    /**
     * Ready and the peer is connected: the only state a payment can route in.
     */
    public var isUsable: Bool
    /**
     * Confirmations so far and how many are needed. Either can be `None`
     * before the node knows it, which is why this is not a percentage.
     */
    public var confirmations: UInt32?
    public var confirmationsRequired: UInt32?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Total sats committed when the channel was opened.
         */channelValueSats: UInt64, 
        /**
         * What can still be sent over this channel, in millisats. This is the
         * ceiling on the next top-up, not `channel_value_sats`.
         */outboundCapacityMsat: UInt64, 
        /**
         * What the pocket could send back, in millisats.
         */inboundCapacityMsat: UInt64, 
        /**
         * The funding transaction has the confirmations the peer required.
         */isChannelReady: Bool, 
        /**
         * Ready and the peer is connected: the only state a payment can route in.
         */isUsable: Bool, 
        /**
         * Confirmations so far and how many are needed. Either can be `None`
         * before the node knows it, which is why this is not a percentage.
         */confirmations: UInt32?, confirmationsRequired: UInt32?) {
        self.channelValueSats = channelValueSats
        self.outboundCapacityMsat = outboundCapacityMsat
        self.inboundCapacityMsat = inboundCapacityMsat
        self.isChannelReady = isChannelReady
        self.isUsable = isUsable
        self.confirmations = confirmations
        self.confirmationsRequired = confirmationsRequired
    }
}

#if compiler(>=6)
extension LightningChannelFfi: Sendable {}
#endif


extension LightningChannelFfi: Equatable, Hashable {
    public static func ==(lhs: LightningChannelFfi, rhs: LightningChannelFfi) -> Bool {
        if lhs.channelValueSats != rhs.channelValueSats {
            return false
        }
        if lhs.outboundCapacityMsat != rhs.outboundCapacityMsat {
            return false
        }
        if lhs.inboundCapacityMsat != rhs.inboundCapacityMsat {
            return false
        }
        if lhs.isChannelReady != rhs.isChannelReady {
            return false
        }
        if lhs.isUsable != rhs.isUsable {
            return false
        }
        if lhs.confirmations != rhs.confirmations {
            return false
        }
        if lhs.confirmationsRequired != rhs.confirmationsRequired {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(channelValueSats)
        hasher.combine(outboundCapacityMsat)
        hasher.combine(inboundCapacityMsat)
        hasher.combine(isChannelReady)
        hasher.combine(isUsable)
        hasher.combine(confirmations)
        hasher.combine(confirmationsRequired)
    }
}



