/**
 * The cleartext routing fields of a v2 two-zone envelope. The host reads them
 * off an inbound sign request to build the matching response header: `subject`
 * and `cmd` are echoed into [`complete_approval`] /
 * [`build_rejection_response`], `sender_did` identifies who sent the
 * request. Only trustworthy alongside a successful [`decrypt_sign_request`] of
 * the same envelope (the header is bound as AEAD AAD, so tampering makes the
 * decrypt fail). Read it for routing, never for authorization.
 */
public struct RoutingHeader {
    public var subject: String
    public var cmd: String
    public var senderDid: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(subject: String, cmd: String, senderDid: String) {
        self.subject = subject
        self.cmd = cmd
        self.senderDid = senderDid
    }
}

#if compiler(>=6)
extension RoutingHeader: Sendable {}
#endif


extension RoutingHeader: Equatable, Hashable {
    public static func ==(lhs: RoutingHeader, rhs: RoutingHeader) -> Bool {
        if lhs.subject != rhs.subject {
            return false
        }
        if lhs.cmd != rhs.cmd {
            return false
        }
        if lhs.senderDid != rhs.senderDid {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(subject)
        hasher.combine(cmd)
        hasher.combine(senderDid)
    }
}



