        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .deviceHardware(kind: try FfiConverterTypeAgentHardwareKind.read(from: &buf)
        )
        
        case 2: return .relayOnly
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

