        switch variant {
        
        case 1: return .unreadable
        
        case 2: return .notAuthentic
        
        case 3: return .expired
        
        case 4: return .unreasonable
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: InviteRefusalFfi, into buf: inout [UInt8]) {
        switch value {
        
        
        case .unreadable:
            writeInt(&buf, Int32(1))
        
        
        case .notAuthentic:
            writeInt(&buf, Int32(2))
        
        
        case .expired:
            writeInt(&buf, Int32(3))
        
        
        case .unreasonable:
            writeInt(&buf, Int32(4))
        
        }
    }
}


