public enum MobileError: Swift.Error {

    
    
    case InvalidInput(detail: String
    )
    case Crypto(detail: String
    )
    case InvalidPayload(detail: String
    )
    case Rpc(detail: String
    )
    /**
     * Reconcile refused because the view of the wallet is partial: these
     * deployed chains' owner sets could not be read. Carried as a list so the
     * host can name them; it has no `CoreError` counterpart because the core
     * expresses it as its own `ReconcileBlocked` type rather than an error.
     */
    case ReconcileBlocked(chains: [String]
    )
    /**
     * The requested owner change cannot be built, and `reason` says why in
     * words meant for the user. Its own variant rather than `InvalidInput`
     * because it is not a programming error: it is the expected answer to a
     * request the chain would reject, delivered before the fee is paid.
     */
    case OwnerChangeRefused(reason: String
    )
}


