        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Crypto(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidPayload(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Rpc(
