            FfiConverterOptionString.write(txHash, into: &buf)
            
        
        case let .skipped(chainId,reason):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .failedTransient(chainId,attempts,lastReason,canRetry):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterUInt32.write(attempts, into: &buf)
            FfiConverterString.write(lastReason, into: &buf)
            FfiConverterBool.write(canRetry, into: &buf)
            
        
        case let .failedPermanent(chainId,code,reason,userActionable):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(chainId, into: &buf)
            FfiConverterTypeErrorCodeFfi.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterOptionTypeUserActionFfi.write(userActionable, into: &buf)
            
        
        case let .lockedAfterMaxAttempts(chainId):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(chainId, into: &buf)
            
        }
    }
}


