public enum SignRequestKind {
    
    case authorizePairing(challengeB64url: String, walletAddress: String, nonce: String
    )
    case transfer(intentId: String, chainId: UInt64, safe: String, signer: String, to: String, amount: String, token: String, rail: TransferRail
    )
    /**
     * `cctp_transport` (RFC-0046): self-to-self cross-chain USDC transport --
     * the owner-signed EVM burn. `to` is the user's own destination-chain
     * account (32-byte mintRecipient, 0x-hex); `destination_domain` is Circle's
     * chain numbering.
     */
    case cctpTransport(intentId: String, chainId: UInt64, safe: String, signer: String, to: String, amount: String, destinationDomain: UInt32
    )
    case x402PaymentErc4337(intentId: String, chainId: UInt64, safe: String, signer: String, payTo: String, amount: String, asset: String
    )
    case x402PaymentEip3009(intentId: String, chainId: UInt64, safe: String, signer: String, payTo: String, amount: String, asset: String, maxTimeoutSeconds: UInt64, eip712DomainName: String, eip712DomainVersion: String
    )
    case solanaTransfer(intentId: String, cluster: String, walletAddress: String, to: String, amount: String, mintAddress: String
    )
    case solanaEscalateRefill(intentId: String, cluster: String, walletAddress: String, mintAddress: String, agent: String, amount: String, payTo: String?, resourceUrl: String?, resourceDescription: String?
    )
    /**
     * Lightning side-wallet top-up (RFC-0040 W4). No amount field on purpose:
     * the core reads it out of `invoice` and puts it in the display fields, so
     * the number the owner sees cannot be a value the daemon chose.
     * `side_wallet_index` selects which of the daemon's own pockets is
     * credited, and the device re-derives that pocket's node id from it, so an
     * invoice signed by anything else is refused rather than paid.
     */
    case lightningEscalateRefill(intentId: String, sideWalletIndex: UInt32, invoice: String, peerAddress: String, resourceDescription: String?
    )
    /**
     * MPP `charge` on Tempo (RFC-0050). `pay_to`, `amount` and `currency` are
     * derived from the resource server's challenge by the core, not supplied
     * by the daemon.
     */
    case mppCharge(intentId: String, challengeHeader: String, resourceUrl: String, resourceDescription: String?, payTo: String, amount: String, currency: String, sender: String, chainId: UInt64, maxFeePerGas: String, maxPriorityFeePerGas: String
    )
    /**
     * MPP Tempo onboarding (RFC-0050): authorize the daemon's agent key on the
     * owner's Tempo account with an on-chain spending limit.
     */
    case mppOnboard(intentId: String, account: String, agentPublicKey: String, limits: [MppTokenLimit], chainId: UInt64, nonce: UInt64, maxFeePerGas: String, maxPriorityFeePerGas: String
    )
    /**
     * MPP Tempo wallet-lifecycle owner op (RFC-0050): the whole owner/limit
     * surface on Tempo (add owner key / revoke key / change limit). No recovery
     * ceremony, no rotation, no M-of-N -- a backup admin key IS the recovery
     * story.
     */
    case mppKeychain(intentId: String, account: String, chainId: UInt64, nonce: UInt64, maxFeePerGas: String, maxPriorityFeePerGas: String, action: MppKeychainAction
    )
}


