// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Operation tag baked into the canonical signed message. Must match
 * the on-chain `Op` enum in `paygent-net/solana-programs::secp256r1_auth`
 * and the client-side [`paygent_solana::GuardOp`].
 *
 * Only the pocket-less, destination-less admin ops (`SetLimit`, `Revoke`,
 * `SetThreshold` -- the new threshold rides the amount field) are built by
 * [`build_solana_guard_message`]. The ops that bind an extra account each
 * have a dedicated builder: `Refill` -> [`build_solana_refill_message`],
 * `AddAgent` -> [`build_solana_add_agent_message`], `SetAgentLimit` ->
 * [`build_solana_set_agent_limit_message`], `Withdraw` ->
 * [`build_solana_withdraw_message`], the owner-membership ops ->
 * [`build_solana_member_message`], `EscalateRefill` ->
 * [`build_solana_escalate_refill_message`].
 */

public enum SolanaGuardOp {
    
    /**
     * Admin-authorized: set / raise the global aggregate per-period
     * refill ceiling.
     */
    case setLimit
    /**
     * Silent-signer-authorized: top up a registered pocket from the vault
     * (`refill` on chain). The mobile typically does NOT sign this; it's
     * the daemon's silent-key path. Its canonical message binds a pocket,
     * so use [`build_solana_refill_message`].
     */
    case refill
    /**
     * Either authority: clear the guard's remaining period budget.
     */
    case revoke
    /**
     * Admin-authorized: sweep funds out of the vault (owner / recovery
     * power). Its canonical message binds a destination, so use
     * [`build_solana_withdraw_message`].
     */
    case withdraw
    /**
     * Admin-authorized: register a new agent pocket with its own
     * per-period ceiling. Its canonical message binds a pocket + ceiling
     * + period, so use [`build_solana_add_agent_message`].
     */
    case addAgent
    /**
     * Admin-authorized: change an existing agent's per-period ceiling.
     * Its canonical message binds a pocket + ceiling + period, so use
     * [`build_solana_set_agent_limit_message`].
     */
    case setAgentLimit
    /**
     * Either authority: deregister an agent pocket. Its canonical message
     * binds a pocket, so use [`build_solana_remove_agent_message`].
     */
    case removeAgent
    /**
     * M-of-N owner-authorized: enroll an additional owner (up to 9). Its
     * canonical message binds the 33-byte member AND the new owner's
     * authorization mode byte (0 = raw P256, 1 = WebAuthn), so use the
     * dedicated [`build_solana_add_owner_message`] (NOT
     * [`build_solana_member_message`], whose mode-less layout the dual-mode
     * guard rejects for AddOwner).
     */
    case addOwner
    /**
     * M-of-N owner-authorized: drop an owner (last-owner removal rejected on
     * chain). A removed key has no mode to bind, so its message stays the
     * mode-less member layout; use [`build_solana_member_message`].
     */
    case removeOwner
    /**
     * Owner-authorized OVER-CAP refill of a registered pocket (escalation
     * Model A). Its canonical message binds a pocket, so use
     * [`build_solana_escalate_refill_message`].
     */
    case escalateRefill
    /**
     * M-of-N owner-authorized: set the owner-signing threshold. Its canonical
     * message is the admin shape with the new threshold in the amount field,
     * so use [`build_solana_guard_message`] with the threshold as `amount`.
     * (R3 retired the silent-set ops AddSilent/RemoveSilent; the daemon silent
     * key is now bound per-agent at `add_agent`.)
     */
    case setThreshold
}


