/**
 * Per-owner authorization mode passed alongside the owner pubkeys when
 * deriving the guard address. Mirrors the on-chain owner-mode byte
 * (0 = raw P256, 1 = WebAuthn) and [`paygent_solana::GuardOwnerMode`].
 *
 * In the V2 commitment each owner is committed together with its mode, so a
 * front-runner cannot land on a victim's guard address while swapping a key
 * from raw to WebAuthn (or back). The mobile must therefore hand the modes in
 * the SAME order as the owner pubkeys, or it derives the wrong address.
 */

public enum SolanaOwnerMode {
    
    /**
     * Raw P256: the owner's signature commits directly to the canonical op.
     */
    case raw
    /**
     * WebAuthn: the owner's signature commits to a WebAuthn assertion whose
     * challenge is a Merkle root binding the canonical op.
     */
    case webAuthn
}


