public enum SubmitGuardError: Swift.Error {

    
    
    /**
     * A previous submission of this exact change was handed to the network and
     * never accounted for. Raised exactly once: discovering it consumed the
     * record, so authorizing again goes through.
     */
    case AmbiguousResubmit(detail: String
    )
    /**
     * The app called the steps out of order -- submitting without arming, or
     * settling twice. A programming error, surfaced rather than ignored,
     * because ignoring it is precisely the missing write-ahead record.
     */
    case OutOfOrder(detail: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSubmitGuardError: FfiConverterRustBuffer {
    typealias SwiftType = SubmitGuardError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SubmitGuardError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .AmbiguousResubmit(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .OutOfOrder(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SubmitGuardError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .AmbiguousResubmit(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .OutOfOrder(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


