/**
 * What the app must do with the durable record now that the submission has
 * reached (or failed to reach) an outcome.
 */

public enum SubmitRecordAction {
    
    /**
     * The network gave a definite answer, so nothing is outstanding: drop the
     * record and let the user act again freely.
     */
    case forget
    /**
     * The call gave no answer at all, so the transaction may be on the network:
     * leave the record where it is. That is what the next attempt trips over.
     */
    case keep
}


