/**
 * The pure half of [`prepare_wallet_creation`], for a wallet whose address is
 * ALREADY KNOWN: the same grants, challenge and statements, without touching
 * the chain.
 *
 * This is what attaching a daemon to an existing wallet signs. The wallet is
 * already there and its address never depended on an agent, so there is
 * nothing to derive -- and re-deriving it would cost two `eth_call`s to arrive
 * back at the value the caller passed in.
 *
 * Callers without an address must use [`prepare_wallet_creation`]: the address
 * is what the grants' subjects name, so an invented one produces a delegation
 * that authenticates and then routes nothing.
 */
public func walletCreationChallenge(ownerDid: String, delegateDid: String, ownerDeviceDid: String, chainId: UInt64, walletAddress: String, expiresAtMs: Int64)throws  -> WalletCreationChallengeFfi  {
    return try  FfiConverterTypeWalletCreationChallengeFfi_lift(try rustCallWithError(FfiConverterTypeMobileError_lift) {
    uniffi_paygent_mobile_core_fn_func_wallet_creation_challenge(
        FfiConverterString.lower(ownerDid),
        FfiConverterString.lower(delegateDid),
        FfiConverterString.lower(ownerDeviceDid),
        FfiConverterUInt64.lower(chainId),
        FfiConverterString.lower(walletAddress),
        FfiConverterInt64.lower(expiresAtMs),$0
    )
})
}

